	private static Color ColorOf( String color )
	{
		Int32[] rgb = [..Regex.Matches( color, @"\d+" ).Select( m => Int32.Parse( m.Value ) )];

		return Color.FromArgb( rgb[0], rgb[1], rgb[2] );
	}


